with temp as (select u.name as results from users as u join movierating as mr on mr.user_id=u.user_id group by u.user_id order by count(u.user_id) desc , u.name asc limit 1),
temp1 as (select m.title from movies as m join movierating as mr on mr.movie_id=m.movie_id and mr.created_at between '2020-02-01' and '2020-02-29'  group by m.movie_id order by avg(mr.rating) desc , m.title limit 1)
select * from temp union all select * from temp1